export interface User {
  user_id: number;
  name: string;
  email: string;
  password: string;
}

export interface Recipe {
  recipe_id: number;
  title: string;
  description: string;
  cooking_time: number;
  difficulty: "Easy" | "Medium" | "Hard";
  user_id: number;
  author_name: string;
  youtube_url?: string;
  image?: string;
}

export interface Ingredient {
  ingredient_id: number;
  name: string;
  quantity: string;
  unit: string;
}

export interface RecipeIngredient {
  recipe_id: number;
  ingredient_id: number;
  amount: string;
}

export interface Step {
  step_id: number;
  recipe_id: number;
  step_number: number;
  instruction: string;
}

export interface Category {
  category_id: number;
  name: string;
}

export interface RecipeCategory {
  recipe_id: number;
  category_id: number;
}

export interface Review {
  review_id: number;
  recipe_id: number;
  user_id: number;
  rating: number;
  comment: string;
  created_at: string;
}

export interface Favorite {
  user_id: number;
  recipe_id: number;
  created_at: string;
}

