export let reviews: Review[] = [];

export let favorites: Favorite[] = [
  { user_id: 1, recipe_id: 1, created_at: "2026-01-15" },
  { user_id: 1, recipe_id: 3, created_at: "2026-02-10" },
];

export const getRecipeCategories = (recipeId: number): Category[] => {
  const categoryIds = recipeCategories
    .filter(rc => rc.recipe_id === recipeId)
    .map(rc => rc.category_id);
  return categories.filter(c => categoryIds.includes(c.category_id));
};

export const getRecipesByCategory = (categoryId: number): Recipe[] => {
  const recipeIds = recipeCategories
    .filter(rc => rc.category_id === categoryId)
    .map(rc => rc.recipe_id);
  return recipes.filter(r => recipeIds.includes(r.recipe_id));
};

export const getRecipeIngredients = (recipeId: number) => {
  const recipeIngs = recipeIngredients.filter(ri => ri.recipe_id === recipeId);
  return recipeIngs.map(ri => {
    const ing = ingredients.find(i => i.ingredient_id === ri.ingredient_id);
    return {
      ...ing,
      amount: ri.amount,
    };
  });
};

export const getRecipeSteps = (recipeId: number): Step[] => {
  return steps
    .filter(s => s.recipe_id === recipeId)
    .sort((a, b) => a.step_number - b.step_number);
};

export const getUserById = (userId: number): User | undefined => {
  return users.find(u => u.user_id === userId);
};

export const getRecipeReviews = (recipeId: number): Review[] => {
  return reviews.filter(r => r.recipe_id === recipeId);
};

export const getAverageRating = (recipeId: number): number => {
  const recipeReviews = getRecipeReviews(recipeId);
  if (recipeReviews.length === 0) return 0;
  const sum = recipeReviews.reduce((acc, r) => acc + r.rating, 0);
  return Number((sum / recipeReviews.length).toFixed(1));
};

export const getReviewCount = (recipeId: number): number => {
  return getRecipeReviews(recipeId).length;
};

export const getUserFavorites = (userId: number): Recipe[] => {
  const favRecipeIds = favorites
    .filter(f => f.user_id === userId)
    .map(f => f.recipe_id);
  return recipes.filter(r => favRecipeIds.includes(r.recipe_id));
};

export const getUserRecipes = (userId: number): Recipe[] => {
  return recipes.filter(r => r.user_id === userId);
};

export const isFavorite = (userId: number, recipeId: number): boolean => {
  return favorites.some(f => f.user_id === userId && f.recipe_id === recipeId);
};

export const toggleFavorite = (userId: number, recipeId: number): boolean => {
  const index = favorites.findIndex(f => f.user_id === userId && f.recipe_id === recipeId);
  if (index >= 0) {
    favorites.splice(index, 1);
    return false;
  } else {
    favorites.push({
      user_id: userId,
      recipe_id: recipeId,
      created_at: new Date().toISOString().split("T")[0],
    });
    return true;
  }
};

export const addReview = (recipeId: number, userId: number, rating: number, comment: string): Review => {
  const newReview: Review = {
    review_id: reviews.length + 1,
    recipe_id: recipeId,
    user_id: userId,
    rating,
    comment,
    created_at: new Date().toISOString().split("T")[0],
  };
  reviews.push(newReview);
  return newReview;
};

export const deleteReview = (reviewId: number): boolean => {
  const index = reviews.findIndex(r => r.review_id === reviewId);
  if (index >= 0) {
    reviews.splice(index, 1);
    return true;
  }
  return false;
};

export const createRecipe = (
  title: string,
  description: string,
  cooking_time: number,
  difficulty: "Easy" | "Medium" | "Hard",
  userId: number,
  categoryIds: number[],
  ingredientList: { name: string; quantity: string; unit: string }[],
  stepList: string[],
  image?: string,
  youtube_url?: string
): Recipe => {
  const newRecipeId = recipes.length + 1;
  const user = getUserById(userId);
  const authorName = user ? user.name : "Chef Cook";

  const newRecipe: Recipe = {
    recipe_id: newRecipeId,
    title,
    description,
    cooking_time,
    difficulty,
    user_id: userId,
    author_name: authorName,
    youtube_url: youtube_url || "https://www.youtube.com/watch?v=kY31O12h-z0",
    image: image || "https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=800&q=80",
  };

  recipes.push(newRecipe);

  categoryIds.forEach(catId => {
    recipeCategories.push({ recipe_id: newRecipeId, category_id: catId });
  });

  ingredientList.forEach(ing => {
    const newIngId = ingredients.length + 1;
    ingredients.push({
      ingredient_id: newIngId,
      name: ing.name,
      quantity: ing.quantity,
      unit: ing.unit,
    });

    recipeIngredients.push({
      recipe_id: newRecipeId,
      ingredient_id: newIngId,
      amount: `${ing.quantity} ${ing.unit}`,
    });
  });

  stepList.forEach((instruction, idx) => {
    steps.push({
      step_id: steps.length + 1,
      recipe_id: newRecipeId,
      step_number: idx + 1,
      instruction,
    });
  });

  return newRecipe;
};

export const addRecipe = createRecipe;

export const deleteRecipe = (recipeId: number): boolean => {
  const index = recipes.findIndex(r => r.recipe_id === recipeId);
  if (index >= 0) {
    recipes.splice(index, 1);
    return true;
  }
  return false;
};

export const findUserByEmail = (email: string): User | undefined => {
  return users.find(u => u.email.toLowerCase() === email.toLowerCase());
};

export const createUser = (name: string, email: string, password?: string): User => {
  const newUser: User = {
    user_id: users.length + 1,
    name,
    email,
    password: password || "hashed_password",
  };
  users.push(newUser);
  return newUser;
};
